owflake.style.width = Math.random() * 6 + 2 + 'px';            snowflake.style.height = snowflake.style.width;            snowflake.style.animationDuration = Math.random() * 3 + 4 + 's';            snowflake.style.opacity = Math.random() * 0.5 + 0.3;            document.body.appendChild(snowflake);            setTimeout(() => snowflake.remove(), 7000);        }        setInterval(createSnowflake, 300);    </script></body></html><?php exit; ?>